-- Analytic and window functions, including KEEP DENSE_RANK and frames
SELECT employee_id, department_id, salary, RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS rnk, DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS drnk, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC, employee_id) AS rn FROM employees;
SELECT * FROM (SELECT e.*, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC) AS rn FROM employees e) WHERE rn <= 3;
SELECT employee_id, salary, SUM(salary) OVER (ORDER BY hire_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM employees;
SELECT order_date, amount, AVG(amount) OVER (ORDER BY order_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7 FROM daily_sales;
SELECT order_date, amount, SUM(amount) OVER (ORDER BY order_date RANGE BETWEEN INTERVAL '7' DAY PRECEDING AND CURRENT ROW) AS week_sum FROM daily_sales;
SELECT employee_id, salary, LAG(salary, 1, 0) OVER (ORDER BY hire_date) AS prev_sal, LEAD(salary) OVER (ORDER BY hire_date) AS next_sal FROM employees;
SELECT employee_id, FIRST_VALUE(salary) OVER (PARTITION BY department_id ORDER BY hire_date) AS first_sal, LAST_VALUE(salary) OVER (PARTITION BY department_id ORDER BY hire_date ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_sal FROM employees;
SELECT employee_id, NTILE(4) OVER (ORDER BY salary) AS quartile, PERCENT_RANK() OVER (ORDER BY salary) AS pr, CUME_DIST() OVER (ORDER BY salary) AS cd FROM employees;
SELECT department_id, MIN(salary) KEEP (DENSE_RANK FIRST ORDER BY hire_date) AS sal_of_earliest, MAX(salary) KEEP (DENSE_RANK LAST ORDER BY hire_date) AS sal_of_latest FROM employees GROUP BY department_id;
SELECT department_id, MAX(last_name) KEEP (DENSE_RANK FIRST ORDER BY salary DESC) AS top_earner FROM employees GROUP BY department_id;
SELECT employee_id, MIN(salary) KEEP (DENSE_RANK FIRST ORDER BY hire_date) OVER (PARTITION BY department_id) AS first_sal FROM employees;
SELECT department_id, SUM(salary) OVER (PARTITION BY department_id) AS dept_total, salary / SUM(salary) OVER (PARTITION BY department_id) AS share FROM employees;
SELECT employee_id, RATIO_TO_REPORT(salary) OVER (PARTITION BY department_id) AS ratio FROM employees;
SELECT employee_id, NTH_VALUE(salary, 2) OVER (ORDER BY salary DESC) AS second_sal FROM employees;
SELECT employee_id, LISTAGG(last_name, ',') WITHIN GROUP (ORDER BY last_name) OVER (PARTITION BY department_id) AS peers FROM employees;
SELECT employee_id, LAG(salary) IGNORE NULLS OVER (ORDER BY hire_date) AS prev_nonnull FROM employees;
SELECT RANK(5000) WITHIN GROUP (ORDER BY salary) AS hyp_rank FROM employees;
SELECT product_id, SUM(amount) OVER (PARTITION BY product_id ORDER BY sale_date ROWS 3 PRECEDING) AS s FROM sales;
SELECT * FROM (SELECT region, product, amount FROM sales) PIVOT (SUM(amount) FOR product IN ('A' AS prod_a, 'B' AS prod_b, 'C' AS prod_c));
SELECT * FROM (SELECT department_id, job_id, salary FROM employees) PIVOT (SUM(salary) AS total, COUNT(*) AS cnt FOR job_id IN ('IT_PROG' AS it, 'SA_REP' AS sales));
SELECT * FROM (SELECT year, quarter, revenue FROM fin) PIVOT (SUM(revenue) FOR quarter IN (1 AS q1, 2 AS q2, 3 AS q3, 4 AS q4)) ORDER BY year;
SELECT * FROM quarterly_sales UNPIVOT (amount FOR quarter IN (q1, q2, q3, q4));
SELECT * FROM quarterly_sales UNPIVOT INCLUDE NULLS (amount FOR quarter IN (q1 AS 'Q1', q2 AS 'Q2'));
SELECT * FROM sales_wide UNPIVOT ((units, revenue) FOR period IN ((u1, r1) AS 'P1', (u2, r2) AS 'P2'));
SELECT * FROM sales PIVOT XML (SUM(amount) FOR product IN (ANY));
SELECT employee_id, COUNT(*) OVER () AS total_rows FROM employees;
SELECT department_id, employee_id, salary, salary - AVG(salary) OVER (PARTITION BY department_id) AS diff_from_avg FROM employees ORDER BY department_id, diff_from_avg DESC;
SELECT SUM(salary) OVER (ORDER BY salary RANGE UNBOUNDED PRECEDING) FROM employees;
